    content: `४. हे महाराज श्रीदत्त दिगंबर...

हे महाराज श्रीदत्त दिगंबर सह्यांचल गिरी के वासी ।।धृ.।।

बद्रिकाश्रम आदि ठिकाना गिरी गिरनार कुवल रस्ता ।
अत्रि ऋषी के पुत्र कहलाए अनसूया जिनकी माता ।
त्रेतायुग अवतार लिनो जी भक्तीमुक्ती के परदाता ।
नाना भेष करत नित श्रीधर अलख निरंजन अविनाशी ।।१।।

कोल्हापूर की भिक्षा मागे अलख जगावे प्रथम प्रहरी ।
पांचाळेश्वर भोजन करके दिन मध्यान्ह पलक ठहरे ।
माहुर गढ की निद्रा सारे देवल ऋषी के वचन हरे ।
पवन स्वरूप करत नित क्रीडा२
स्नान करत नित उठ काशी ।।२।।

अलक के त्रय ताप निवारे गोरख को प्रबोध किया ।
सहस्रार्जुन को सहस्र भुजा शंकराचार्य वर पाया ।
परशुराम को मिले दिगंबर कावडी कोंभ नजर आया ।
कोरी भुमी का दहन बतायो२
आदिभवानी परकाशी ।।३।।

दीनदयाल कृपाधन सागर पूरणब्रह्म कलाधारी ।
ज्ञान दियो यदुराजा तारे दत्त दिगंबर छबी न्यारी ।
निर्गुण स्वरूप अवतार लिनो जी भुक्तीमुक्ती के अधिकारी ।
श्यामकरण शत पाच पठायो२
पावन हो गये ऋचिक ऋषी ।।४।।

हे करुणाशा प्रणाम हमेशा अर्ज हमारी सुन लेना ।
हम दरबारी नोकर खासे तलब हमारी भर देना ।
रखो मेहर की नजर हमेशा ना जानू कब है मिलना ।
दास बहादुर शरण चरण पर२
टालो दुःख आपत्ती ।।५।।`
