    content: `२२. सुंदर मूर्ती श्रीदत्ता...

सुंदर मूर्ती श्रीदत्ता तुम्ही दावा मज नयनी ।
कशी बा खंत धरली मनी ।।धृ।।

बहु सृष्टीचा मी अन्यायी म्हणुनि झाले उदास । कशी पाहीना माझी वास ।
पुन्हा पुन्हा मज ज्ञान दिधले, मी दवडिले त्यायास । नाही मोडिले प्रसवास ।
गुरुवचनाचा भंग मी केला तेही झाले उदास । आता मी करू कवणाची आस ।
मार्गद्रोही पात्र दुखविले कठीण शब्द बोलुनि ।
कशी बा खंत धरली मनी ।।१।।

मी विषयासि जन्म दिधला नाही दिला स्वामीला । दोष मी बहुतांचा घेतला ।
ज्ञान भक्ती वैराग्य सांडुनि गेलो उपाधीला । धुरुनि मी बसलो स्वग्रामाला ।
सहा वचनांचा आचार स्वामी सांगुनि मजला गेला । शेवटी तोही नाही झाला ।
भिक्षा विधी पंधरा वचने घडतील ज्या पुरुषाला । सोळावे प्रमाण त्या काल्याला ।
वैसे जाणुनि इंद्रियार्थ घेतले मागुनि ।
कशी बा खंत धरली मनी ।।२।।

सव्वीस वचने त्याग बोलिले, अविद्येत राहुनि । सुख मानमान्यता भोगुनि ।
गडीसिडीची वचने सारे ठेविली बांधुनि । अष्टभोग सेवितो नित्यानी ।
चहु प्रकारे स्मरण बोलिले हृदयी आलिंगुनि । त्यात एक प्रहर दिला नेमुनि ।
तव्हेळी मज निद्रा येते अविद्येची झडपणी । स्वामीची दृष्टी जाए फिरुनि ।
ती प्रकारी अयोग्यता जडली मुळीहुनि ।
कशी बा खंत धरली मनी ।।३।।

ऐसा मी अपराधी खोटा दगलबाज मी फार । दुखविले स्वामीचे अंतर ।
म्हणौनि माझी खंत आली मज केला अवहेर । उतरला निडलावरचा कर ।
दया मया गुण ईश्वरी म्हणुनि अंगीकार । नाहीतर दुःखाचे डोंगर ।
घडवी दान, पुरवी भजन, चुकवी दुख थोर । नाही कणवेची ठेविली उर ।
अळकाचे त्रिताप हरिले दर्शन देउनि ।
कशी बा खंत धरली मनी ।।४।।

उदार होसि, जीव उद्धरीसि पैजा तू घेउनि । अंती मज भेट द्यावी येऊनि ।
तुजवांचुनि कोण तारील संकष्टापासुनि । श्रीचरणी मस्तक ठेउनि ।
बुडतो आता भवरोगरी कोण आणू बोलाउनि । स्मरू कवणाचे नाव घेउनि ।
रिलोप किंकर विनवी स्वामीला चित्त मन लाउनि ।
कशी बा खंत धरली मनी ।।५।।`
