    content: `५. प्रभुराजा सृष्टीचा अवतरला भुवनी...

प्रभुराजा सृष्टीचा अवतरला भुवनी । प्रभू प्रकटला धरणी चहयुगी क्रीडतो त्रिविधा अवतारी ।।धृ।।

उत्तम धूप दीप सुगंध परमेश्वर हेतू । पुजिला सर्वत्र सद्भावे जगतु ।।१।।

सकळही तीर्थातीर्थी प्रभूचरण स्थानी । प्रेमानंदा वस्तू श्रीचक्रपाणी ।।२।।

आदि सृष्टीचा दाता सर्वज्ञ स्वामी । ज्ञान, बोधकरी जीवा उद्धरी परधर्मी ।।३।।

निर्गुणचित्पर ब्रह्म झाले साकार । जीव उद्धरणासाठी आले महिवर ।।४।।

कृति शुक्ल वर्ण त्रेती आरक्त । द्वापरी नीलवर्ण कलि मा जी पीत ।।५।।

किंकर मुनिराजेया शरणांगता स्वामी । देऊनि सन्निध प्रेम उद्धरी परधर्मी ।।६।।`
