    content: `१०. श्रीचक्रपाणि प्रभु अवतार जन्मकाळ आरती...

जय जय श्रीचक्रपाणि देवा, फलटण क्षेत्री अवतारा ।
द्वितीय अवतार पंचकृष्णांमधी जगदुद्धारा ।।धृ.।।

जनक राजा आणि जनक आई गृही अवतरले ।
बाललीळा करुनिया भक्तांसी उद्धरिले ।।
कमलनयन सुंदर रूप मूर्ती मनमोही ।
ओवाळू आरती प्रभू चक्रपाणि पायी ।।१।।

कमळजादेवी चरणी लीळा दाखविली ।
अमरापूर क्षेत्री भक्तांसि दीक्षा दिधली ।।
दास नामा विनवी चरणकमली ठेवा ।
अवतार जन्मकाळी करितो मंगल सेवा ।।२।।`
