    content: `११. श्रीगोविंदप्रभू अवतार जन्मकाळ आरती...

जय जय श्रीगोविंदप्रभू स्वामी, ऋद्धपुरीचा राजा ।
तृतीय अवतार पंचकृष्णांमधी जय जय ध्वजा ।।धृ.।।

काण्वशाखा द्विजकुळी जन्म घेतला प्रभूने ।
ऋद्धपूर क्षेत्र पावन केले निज तेजाने ।।
अद्भुत लीळा दाखविली बालपणी देवा ।
ओवाळू आरती नित्य श्रीप्रभूजी सेवा ।।१।।

दयाळू कृपाळू स्वामी भक्तांचा आधार ।
भक्ती प्रेम भावे करितो ओवाळणी वारंवार ।।
कवी मुरारी स्तवितो अवतार जन्मकाळा ।
कृपा करी स्वामी मज दीनावरि गोपाळा ।।२।।`
