    content: `१२. सर्वज्ञ श्रीचक्रधर स्वामी अवतार जन्मकाळ आरती...

जय जय श्रीचक्रधर स्वामी, पंचम अवतार परब्रह्म ।
भडोच नगरी जन्म धरोनि उद्धरिले अवघे जन ।।धृ.।।

विशालदेव राजा आणि म्हाळसादेवी गृही आले ।
हरिपाळदेव नामे बालपणी प्रभू शोभले ।।
रिद्धपूर क्षेत्री गोविंदप्रभूंनी शक्ती दिधली ।
महाराष्ट्रात महानुभाव पंथाची गंगा वाहिली ।।१।।

लीळाचरित्र सूत्रपाठ सिद्धांताची खाण ।
जीव उद्धारासाठी दिधले ब्रह्मज्ञान ।।
दास तुका विनवी चरणकमलासी ।
ओवाळू आरती जन्मकाळ समयी प्रभूसी ।।२।।`
