    content: `१३. पंचकृष्ण अवतार मंगल जन्मकाळ आरती...

ओवाळू आरती पंचकृष्णांची, अवतार जन्मकाळाची ।
जय जयकार करो अवघी दुनिया, स्वामी चक्रधरांची ।।धृ.।।

श्रीकृष्ण दत्त चक्रपाणि गोविंदप्रभू स्वामी ।
पंचम चक्रधर स्वामी अवतरले या भूमी ।।
पंच अवतार एकच तत्त्व परब्रह्म रूप ।
जीव उद्धारासाठी प्रकटले अनुप ।।१।।

पुष्पवृष्टी होती देवांवरि देव दुंदुभी वाजती ।
ऋषीमुनी भक्तजन आनंदे गुण गाती ।।
धूप दीप सुवासिक आरती ओवाळू शिरी ।
सदा राहो कृपा स्वामींची आमुच्या शिरी ।।२।।`
