    title: '१६. पाळणा श्रीकृष्णाचा (माता यशोदा देई - पाळण्यांस झोले...)',
    content: `१६. पाळणा श्रीकृष्णाचा

माता यशोदा देई - पाळण्यांस झोले
देवकीचे बाळ बाई नंदाघरी आले ।।धृ।।

मांडीवरी झोपी जाता । कुण्या माऊलीचा तान्हा
आईपणं जागे झाले । फुटे यशोदेला पान्हा
पीता अमृताच्या धारा । बाळ झोपी गेले ।।देवकीचे।।१।।

गोकुळंच्या माऊल्यांनो । दुधं आणा वाटी वाटी
हळूहळू वाढे कान्हा । भुक झाली याची मोठी
याच्या काळजीची माया । माझ्या उरी चाले ।।देवकीचे।।२।।

आईबापं ठावं नाही । माझ्या लाडक्या कृष्णाला
याच्या माऊलीच्या दैवी । मथुरेची बंदीशाळा
रोपं यादू वंशाचे । दारी लावीयेले ।।देवकीचे ।।३।।

रांगतो हा बाळ तान्हा । लीळ बघा सावळ्याची
तितं लावा गाली कुणी । दृष्ट काढा तान्हुल्याची
लीळ पाहुनीया याच्या । देव भ्रमीत झाले ।।देवकीचे ।।४।।

जोजवा गे जोजवा । कुणी माझ्या लाडक्याला
मुरली ओठावरी याच्या । तसाबाई झोपी गेला
बाल लीला गं याने । विश्व मोहवीले ।।देवकीचे ।।५।।`
