    content: `१८. पाळणा - प्रभू कृष्ण नामाने

प्रभु कृष्ण नामाने प्रकटले हो, प्रभु कृष्ण नामाने प्रकटले ।
प्रकटताचि विज्ञान खेळिले, वसुदेव चकितचि झाले ।।धृ।।

जन्मताचि देवकी मातेसि चतुर्भुज दर्शन दिले ।
दुथडी यमुना पार करूनि यशोदेचे बालक झाले ।
गोकुळ नगरी गोपगोपिका, मोहूनि वेडेचि झाले ।।१।।

मानव सोडा पशुपक्षीही जळचरे वेधुनि गेली ।
कृष्णवियोगे वृंदावनाची झाडे सुकूनचि गेली ।
कंस चाणूर मर्दन करूनि, मातापिता मुक्तचि केले ।।२।।

ज्ञानशक्तीचा स्वीकार करूनि उद्धवासि प्रेम देउनि ।
एका खांबाची सुवर्णनगरी वसविली समुद्राभितरी ।
विचित्र लीळा करूनि तयाने, जग विस्मितचि केले ।।३।।

सोळा सहस अंतापुरासि सप्त पट्टराण्यांसि ।
विज्ञानमूर्तीचा योग अवघ्यासि रुक्मिणी प्रेमप्रदासि ।
छप्पन कोटी यादव सारे, अवघे अभागिचि ठेले ।।४।।

चक्र सुदर्शन करी घेउनि शिशुपाळ वध करूनि ।
अग्रपूजेचा मान घेउनि क्षीरभोजन वाडुनि ।
प्रभुने ऐसी लीळा करूनि, नम्रतेचे धडेचि दिले ।।५।।

अर्जुनदेवा निमित्त करूनि, गीतामृत पाजुनि ।
काळांतरीचा नष्ट झालेला योग शुद्ध करूनि ।
भगवद्गीतेत द्वैत मांडुनि, संसारविषचि बोले ।।६।।

कुंतीएसि प्रेम दिधले पांडव उद्धरूनि नेले ।
कविने आपुले वेडेवाकडे काव्यपुष्प वाहिले ।
प्रसन्न होऊनि प्रेमचि देतील ऐसेचि मनोरथ केले ।।७।।`
