    content: `३. जय अत्रीकुमारा सुकुमारा...

जय अत्रीकुमारा सुकुमारा,
भवदोश क्लेश त्रयतापहरा ।।धृ।।

निजकृपे ज्ञान दे यदुराया,
गोरक्ष बोधी दावुनि माया,
ऋचिकासि पंचाशत अर्पी हया ।
सहस्रार्जुना वरकर दिधले,
रेणुकजा मही दाउनि वहिले ।
करउनि शुभनिक्षेप ।।१।।

जगी मान्य करूनि शंकराचार्या,
याचका पुरवीसि शुभकार्या,
मदळसा वाचवी शुभभार्या ।
त्रयतापी अळक शांतविला,
निगदाचार्या पटी स्थापिला ।
निर्मितसे परंथ ।।२।।

काशीश्वर नृपतीवचनाला,
दे मान स्नान करी काशीला,
ले तिळा अक्षता निढाळा,
भद्रिकाश्रमी मग जाऊनि,
कर्णितसे बहुमत निजश्रवणी,
ऋषीमुखी पुराण ।।३।।

जंबुकाख्य नगरी करी भिक्षा,
पांचाळपट्टणी कमलाक्षा,
मग येणे होए हो जगसाक्षा,
आत्मतीर्थी गंगोदरी असुनि,
भोजन सारितसे नित्यानी,
गमन करी तेथून ।।४।।

मातापूर शयनी करी निद्रा,
जो वंद्य जगत् हरि विधी रुद्रा,
जय करूणाघन प्रभु परचंद्रा,
शिवप्रिय बंधु भिद विनवितो,
वरमती द्या मज जयरूप स्तवितो
वंश परांडेकार ।।५।।`
