    content: `३. जयदेव जयदेव जय परमानंदा

जयदेव जयदेव जय परमानंदा ।
अंगीकारा पविते माधव गोविंदा ।।धृ।।

शके रूद्र निधी अयना मूळ श्रावणमासा
बीड भुवनी प्रभूराजा करी चातुर्मासा
चतुर्दशी शुक्लाची शुभ दिन भृगु खासा
नक्षत्र श्रवणाचे करू मंगल घोषा ।।१।।

रम्यलय स्थळ उत्तम अनुसरसह वसति
धूप दीप मंगल सुमने नित पूजन करिती
सिंहासनी मम स्वामी अनुपम श्रीमूर्ती
आद्याचार्य ज्यांची भक्तामध्ये कीर्ती ।।२।।

पविते पर्वणी अवसर सिंहासनी बसूनी
केळी नारळ पोफळ पुष्पादिक आणूनी
सुमन वस्त्रा पितांबर मुनिवृंदी मिळूनी
पूजिला जगत्रनायक प्रेमाची जननी ।।३।।

परंपरेने हा विधी परमार्गी करिती
अंगीकारा स्वामी जय चक्रवर्ती
धूप दीप कर्पूर आरती तव मंगल कीर्ती
अगम्य जयतारख्या हे सत्कीर्तन स्फूर्ति ।।४।।`
