    title: '९. निशीदिनी आठवा हो श्रीगोविंदप्रभुना (Nishidini Aathva Ho Shree Govindaprabhuna)',
    content: `९. निशीदिनी आठवा हो श्रीगोविंदप्रभुना

निशीदिनी आठवा हो श्रीगोविंदप्रभुना ।
स्मरोनिया त्यांच्या अगम्य लीळा ॥धृ॥

रांधवनहाटी प्रभु खेळक्रीडा करिति ।
सेंगुळबुरुडाची चवी प्रभु चाखति ।
स्वामीकडे फेकुनि म्हणति २ घे घेना याला २ ॥१॥

पाठीवरी थाप हो श्रीप्रभु देति ।
निरंतर स्वामी ती आठवीति ।
मेली जाए चक्रा होशी २ । म्हणति स्वामीला २ ॥२॥

माहेरीचे नव्हते कोणी सासुरवासिणीला ।
मायबाप होऊनि तिचा ताप निवविला ।
जीवा सुखदानी ऐसा २ श्रीप्रभु झाला २ ॥३॥

येथुनि हो तुम्हा आता गोविंदगती ।
श्रीचक्रधर स्वामी आउसाला म्हणति ।
येथीचे श्रीगुरु म्हणुनि भजा श्रीप्रभुला २ ॥४॥

नागदेवासवे सर्व भक्तीजन आले ।
करुनियां सेवा त्यांनी प्रभु तोषविले ।
विनय म्हणे आठवा हो श्रीगोविंदप्रभुला २ ॥५॥`
