    title: '११. श्रीदत्तराया साह्य कराया असो कृपेची छाया (Shree Dattaraya Sahya Karaya)',
    content: `११. श्रीदत्तराया साह्य कराया असो कृपेची छाया

श्रीदत्तराया साह्य कराया असो कृपेची छाया
आम्हावरी असो कृपेची छाया ॥धृ॥

अज्ञानी मी अन्याज्ञानी ।
नाही लागलो ईश्वरधर्मी ।
अन्य देवते शरण जाऊनि ।
दुःख भोगिले हे देवराया ॥१॥

अनेक जन्म आलो फिरुनि ।
परि न ओळख तुमची अर्जुनि ।
तूच कृपेचा सागर असुनि ।
दर्शन देई हे देवराया ॥२॥

श्याममंडळची हीच आशा ।
पुरवी स्वामी श्रीजगदीशा ।
चुकलो तरी आम्ही सेवा कराया ।
घेई पदरी श्रीदत्तराया ॥३॥`
