    title: '१२. श्रीचक्रधर स्वामी ते सोडुनि गेले (Shree Chakradhar Swami Te Soduni Gele)',
    content: `१२. श्रीचक्रधर स्वामी ते सोडुनि गेले

श्रीचक्रधर स्वामी ते सोडुनि गेले ।
नागदेव आचार्यांच्या मनी दुःख थोर झाले ॥धृ॥

सर्वज्ञाविण नागदेव ते उदास झाले त्यासमयी ।
विरहाग्नी भडकला भयंकर शांत होईना तो हृदयी ।
सुख चैन नाही मनी तळमळतो ।
जळाविण मासा कसा तडफडतो ।
जणू काही त्यांच्यावरती आकाश पडले ।
सौख्य जीवाचे ते छिन्नभिन्न झाले ॥१॥

ईश्वरध्यासामध्ये तयाला देहभान ना राहिले ।
स्वामीविना कधी आन येईना नामही त्यांच्या मुखामधी ।
दैनंदिनी श्रीचक्रधर द्या म्हणुनि उरके भिक्षाविधी ।
खानपान त्यांच्या जीवा आवडेना ।
लोचनातले ते अश्रू आवरेना ।
नागदेव झाला ऐसा देवाविण वेडा ।
क्षण होत चाले पहा त्यांचा देह गाढा ।
शरीराचे दश इंद्रिय सारे शिथिल अतिशय जाहले ॥२॥

उत्कंठे अनुराग अनास्थे भ्रमण करीतसे नित्यदिनी ।
अचल होउनि जाउनि पडले भानखेडीच्या रम्य वनी ।
पंचप्राण त्यांच्या कंठी एकवटति ।
निघोनिया जाऊ पाहे जीवज्योती ।
नागदेव आचार्य ते विस्मृत पडले ।
देह वाळविने सारे व्यापून गेले ।
गोवळियाने मुखी कुरधने पिळुनि तयासि राखिले ॥३॥

महदंबा ती ऋद्धपुरासि आली ढुंडाळित भक्तासि ।
नागदेव तो कुठे गेला विचारिले तिने श्रीप्रभुसि ।
सांगितली खूण प्रभुनेही तिजला ।
मेली जाए म्हणे भानखेडीयाला ।
निघाली रूपाई अतिशीघ्रतेने ।
गोरक्षाकिस आधी विचारुनि तिने ।
अतिप्रयत्ने आचार्यांसि शोधुनिया तिने काढिले ॥४॥

विविध प्रकारे उपाय करूनि सावध केले त्यास त्वरी ।
महदंबा वदे नागदेवा उठ देव आहे चल ऋद्धपूरी ।
नागदेव म्हणे तो नाही देव माझा ।
श्रीचक्रधर स्वामी कैवल्याचा राजा ।
महदंबा म्हणे तुज निरोविले श्रीप्रभुला ।
अशी देववाणी का तू विसरून गेला ।
दामोदर म्हणे सुबोध करूनि ऋद्धपुरासि आणिले ॥५॥`
