    title: '४४. योगेश्वर श्री चक्रधराला विसरु नको अंतरी (Yogeshwar Shree Chakradharala Visaru Nako Antari)',
    content: `४४. योगेश्वर श्री चक्रधराला विसरु नको अंतरी

योगेश्वर श्री चक्रधराला विसरु नको अंतरी।
तयाला भक्तीने वश करी।।धृ।।

जपतप साधन लागत नाही,
धन दौलत ही नकोच काही।
आसनी शयनी आठव तयाला,
बसुनी मठ मंदीरी।।१।।

नागदेव माहीमभट्टासम ती,
करील नर जो अनन्यभक्ती।
मानव जन्म धन्य तयाचा,
आज या भुमीवरी।।२।।

भक्ती विना कधी जिवास मुक्ती,
मळत नाही बघ या त्रय जगती।
दामोदर मुनी सांगतसे हे,सकाळ जणा बहु परी।।३।।`
