    title: '४७. हे देवा श्री चक्रधरा, जगी तुझाच रे आसरा (He Deva Shree Chakradhara Jagi Tujhach Re Aasara)',
    content: `४७. हे देवा श्री चक्रधरा, जगी तुझाच रे आसरा

हे देवा श्री चक्रधरा,जगी तुझाच रे आसरा।
नसे कोणी मला,किव येऊ दे तुला,
घे पदरी तुझ्या पामरा।।धृ।।

नाम नेणे तुझे धाम रे,मारु कैसी तुला हाक रे।
तु दयाळु खरा,ममताळु बरा,
प्रेम देसीयल या किंकरा।।१।।

नको विसरु अरे माधवा,देई दर्शन मला केशवा।
तु दीनबंधु असे,जगी मानितसे,
नसे दुजा सखा सोयरा।।२।।

पाजी अमृतपाणी तुझे, चरणी पदलीन आहो तुझे।
ही हाक माझी,जरा ऐका त्वरी,
नेई बाबुसी आपल्या घरा।।३।।`
