    bookId: 'panchavtar_bhajan_book',
    number: 59,
    title: '५९. अनाथाच्या नाथा श्रीचक्रधरराया (Anathachya Natha Shree Chakradhararaya)',
    content: `५९. अनाथाच्या नाथा श्रीचक्रधरराया

अनाथाच्या नाथा श्रीचक्रधरराया ।
वेळ का लावीता मला भेट द्याया ।।धृ।।

मी महापापी सदा कर्म हीन ।
कृपाळुपणे देवा दाखवी श्रीचरण ।
विनंती करीतो स्वामी तुमचाचं पाया ।।१।।

भरवस नगरी धरीला अवतार ।
महाराष्ट्री येऊन केला जीवांचा उद्धार ।
झडक्री येई देवा मला भेट द्याया ।।२।।

दास म्हणे देवा जोडूनिया कर ।
बहु दुःख झाले नको हा संसार ।
अविद्या छेदूनी न्यावे तुमच्याच ठाया ।।३।।`
