    title: '६०. दाही दिशा उजळल्या, पावन झाली धरा (Dahi Disha Ujalalya Pavan Jhali Dhara)',
    content: `६०. दाही दिशा उजळल्या, पावन झाली धरा

दाही दिशा उजळल्या, पावन झाली धरा ।
नादध्वनी उमटतसे कानी
जयजय चक्रधरा ।।धृ।।

कुठे फडकते निशान अंबरी गर्जत संदेशा ।
आठशते नवक्रांती घडली महाराष्ट्र देशा ।।१।।

कुठे विजनी चर्चा होई दिन रात सजनी ।
चक्रधरांच्या तत्वज्ञाना पढतात ज्ञानी ।।२।।

घराघरातून विषमतेतून मानव हा जगतो ।
त्या विषमते शमवी ज्ञाने संत साधू पहातो ।।३।।

धरा प्रेम मनी भूतमात्रांचे दया हृदयी ठेवा ।
अनित्य हा संसार मानवा प्रेम नित्य ठेवा ।।४।।

शाश्वत पद जर हवे तुला तर कर ईश्वर भक्ती ।
अनन्यतेने सर्व परीने मग लाभे मुक्ती ।।५।।`
