    bookId: 'panchavtar_bhajan_book',
    number: 65,
    title: '६५. घ्या घ्या सदा सुवाचे, प्रभु नाम माधवाचे (Ghya Ghya Sada Suvache Prabhu Nam Madhavache)',
    content: `६५. घ्या घ्या सदा सुवाचे, प्रभु नाम माधवाचे

घ्या घ्या सदा सुवाचे, प्रभु नाम माधवाचे ।
तुटतील पाश सारे, एका क्षणी जिवाचे ।।धृ।।

प्रभु नाम एक नौका, बसता जिवा न धोका ।
तिळमात्र घ्याल शंका, तरी स्थान रौरवाचे ।।१।।

प्रभु नाम हे विमान, दाविल मोक्षधाम ।
तिथे मिलेल श्याम, ते हृदय यादवाचे ।।२।।

प्रभु नाम द्रौपदीने, जब घेतले मुखाने ।
संकष्ट माधवाने, तव वारीले जिवाचे ।।३।।

सुख चैन सर्व भास, नैश्वर महाविलास ।
प्रभुची धरावी कास, सुख हेची मानवाचे ।।४।।`
