  {
    id: 'pancha_bhajan_68',
    bookId: 'panchavtar_bhajan_book',
    number: 68,
    title: '६८. घडोधडी आठवा हो करुनिया वर्दन श्रीप्रभुला (Ghadoghadi Aathva Ho Karuniya Vardan Shree Prabhula)',
    content: `६८. घडोधडी आठवा हो करुनिया वर्दन श्रीप्रभुला

घडोधडी आठवा हो२ करुनिया वर्दन श्रीप्रभुला ।
जिवा रक्षण्याला करुणाघनाला ।।धृ।।

भाद्रपद मासी शुध्द त्रयोदशीला,
अवतरले प्रभु काटसुऱ्याला ।
जिवा दवडुनी हो२ पाठवी तयासी फळाला ।।१।।

वेड्या पिश्या परी,प्रभु करीतो क्रीडेला,
जाय मेली होई ब्रम्हा म्हणती कृमीला ।
पांगुळ्यासी पाय हो२ वाचा देतीय पहा मुक्याला ।।२।।

ऐशा नाना लिळा,पहा ऋध्दपुरी,
परमेश्वरपुरी गोविंद नगरी ।
श्रीप्रभु जयंतीला हो२ चला चला जाऊ ऋध्दपुराला ।।३।।

प्रतिदिनी साठ जिवा,मोक्षदान दिले,
नाना चमत्कार जिवा दाखविले ।
विनय म्हणे जय जय हो२ भजा गोविंदप्रभुला ।।४।।`
  },
  {
    id: 'pancha_bhajan_69',
    bookId: 'panchavtar_bhajan_book',
    number: 69,
    title: '६९. हे माझ्या धर्म बंधुनो, जरा अश्रू येऊ द्या नयनी (He Majhya Dharma Bandhuno)',
    content: `६९. हे माझ्या धर्म बंधुनो, जरा अश्रू येऊ द्या नयनी

हे माझ्या धर्म बंधुनो । जरा अश्रू येऊ द्या नयनी ।
ती आठवा स्मृति वीरांची । कसे देह क्षेपिले त्यांनी ।।धृ।।

द्या मान वंदना त्यांना । धर्मासी राखिले ज्यांनी ।
कुणी नराधम तो आला । दामोदर पंडीताला ।
करुनिया लक्ष अचानक । घातला तयाने घाला ।
पुढे होऊनी वार तयाचा । झेलिला केसोबासांनी ।।१।।

एक दि भटोबासांनी । कोथळोबा मुख्य करोनी ।
देशावर जाईल कोणी । म्हणीतले परा वाचेनी ।
कोथळोबास देशावर । निघाले खांडे काढोनी ।।२।।

एकदा कविश्वरबास । सह दंती गोपाळबास ।
दुष्काळी निघुन गेले । नित्य नेम विधी अटणास ।
अन्नछत्री भिक्षा न मिळता । मग देह पाडी सुकवोनी ।।३।।

ती नाती नागाईसा । गेली सप्तश्रऊंगासी ।
पहा कसे देह क्षेपिले । लाजविले तिने आम्हासी ।
छिन्नस्थळी आणली शोधुनी । तेथुनी कविश्वरांनी ।।४।।

ते रामदेव ज्वरी पिडले । भटोबासी त्या आडविले ।
तेही ना त्यांनी ऐकिले । अन प्रेम पद मिळविले ।
रामदेव रणामध्ये पडले । वाणीले भटोबासांनी ।।५।।

हे शास्त्राचे भांडार । देईल धर्मी आधार ।
भटोबासांचे आभार । मानीतसे आज मी आज मी थोर ।
थोडा तरी दीन दयाळा । घे बोध तया पासौनी ।।६।।`
  },
  {
    id: 'pancha_bhajan_70',
    bookId: 'panchavtar_bhajan_book',
    number: 70,
    title: '७०. स्वामी वियोग - पापीयाला टाकुनिया स्वामीराया दुर गेला (Swami Viyog - Papiyala Takuniya Swamiraya Dur Gela)',
    content: `७०. स्वामी वियोग - पापीयाला टाकुनिया स्वामीराया दुर गेला

पापीयाला टाकुनिया स्वामीराया दुर गेला ।
तुजविणे देह माझा प्रभु भू ला भार झाला ।।धृ।।

कृपादृष्टी करुनी दिधले,प्रतिसृष्टी ज्ञान मजला ।
अधमतीने घालविले,मीच माझा घात केला ।
अनंत सृष्टी विश्वहननी,अघाचा मी ढिग केला ।
महापात्र ज्ञानीयांचा,छळ शब्दे नित्य केला ।।१।।

काळबोटा परी खोटा,कृतीचा मी वंचकीया ।
तरी तारी दुःख वारी,भवारी भो स्वामीराया ।
षडविध प्रमादाते,आचरीता जन्म गेला ।
अष्टभोग नित्य सेवी,तेणे खंती आली तुजला ।।२।।

कुमरत्वयुक्त पात्री,दोष मिथ्या कल्पिले मी ।
साधनासी नित्य निंदी,चाळी जायबावीसी मी ।
पुढीलाची श्रेष्ठ चर्या,पाहुनिया निंदी त्याला ।
मनी गर्व धरुनियां,श्रेष्ठ मानी आपुल्याला ।।३।।

दीनबंधु कृपासिंधु,अविद्येचा बंध छेदी ।
दीनानाथा अनंता हा,दास तुझा पाद वंदी ।
दास पंचसरीताख्य,प्रभाकर हा प्रार्थी तुजला ।
तृषाकांत फार झालो,पाजी स्वामी प्रेम प्याला ।।४।।`
  }
